mapper.select:
SELECT COUNT(1) FROM fund_system
WHERE deleted = 0

    AND status = #{status}


    AND apply_time >= #{startDateTime} and apply_time  <=  #{endDateTime}

SELECT SUM(apply_amount) FROM fund_system
WHERE deleted = 0

    AND status = #{status}


    AND apply_time >= #{startDateTime} and apply_time  <=  #{endDateTime}

SELECT fund_type AS name, COUNT(1) AS value FROM fund_system WHERE deleted = 0
AND status = #{status}
AND apply_time >= #{startDateTime} and apply_time <= #{endDateTime}
GROUP BY fund_type

SELECT
fund_type AS name,
COUNT(1) AS value
FROM fund_system AS f LEFT JOIN student_info AS s ON f.student_id = s.id
WHERE f.deleted = 0

    AND f.status = #{status}


    AND s.grade = #{grade}


    AND f.apply_time >= #{startDateTime} and f.apply_time  <=  #{endDateTime}

GROUP BY fund_type

SELECT s.grade AS name, COUNT(1) AS value FROM fund_system AS f LEFT JOIN student_info AS s ON f.student_id = s.id WHERE f.deleted = 0
AND f.status = #{status}
AND f.apply_time >= #{startDateTime} and f.apply_time <= #{endDateTime}
GROUP BY s.grade ORDER BY s.grade
